uint16_t                     report_periodicity_opts::to_number() const
{
  switch (value) {
    case ms1000:
      return 1000;
    case ms2000:
      return 2000;
    case ms5000:
      return 5000;
    case ms10000:
      return 10000;
    default:
      invalid_enum_number(value, "report_periodicity_e");
  }
  return 0;
}

